# 一键查看防护状态（复制这一行运行就行）
echo "🛡️ 防护状态 | 封禁IP: $(iptables -L -n 2>/dev/null | grep REJECT | awk '{print $4}' | uniq | wc -l)个 | 今日攻击: $(grep "$(date +%Y-%m-%d).*Found" /var/log/fail2ban.log 2>/dev/null | wc -l)次 | 最近5分钟: $(grep "Found" /var/log/fail2ban.log 2>/dev/null | awk -v start="$(date -d "5 minutes ago" "+%Y-%m-%d %H:%M:%S")" '$1" "$2 >= start' | wc -l)次"